<?php
require_once __DIR__ . '/config/config.php';
requireLogin();
if (!can('users', 'view')) { die('Admin access required.'); }

$files = [
    'modules/output/form.php' => '',
    'modules/fob/form.php' => '',
    'modules/fob/list.php' => '',
    'modules/tickets/action.php' => '',
    'modules/fob/action.php' => '',
    'modules/output/list.php' => '',
    'modules/output/action.php' => '',
];

$baseDir = __DIR__;
$errors  = [];
$done    = [];

if ($_POST['go'] ?? false) {
    foreach ($files as $relPath => $b64content) {
        $absPath = $baseDir . '/' . $relPath;
        $dir     = dirname($absPath);

        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
        }
        if (!is_dir($dir)) {
            $errors[] = "Cannot create dir: $dir (is_writable parent: " . (is_writable(dirname($dir)) ? 'yes' : 'no') . ")";
            continue;
        }

        $content = base64_decode($b64content);
        if ($content === false) {
            $errors[] = "Bad base64 for: $relPath";
            continue;
        }

        $bytes = file_put_contents($absPath, $content);
        if ($bytes === false) {
            $errors[] = "Write failed: $relPath (dir writable: " . (is_writable($dir) ? 'yes' : 'no') . ")";
        } else {
            $done[] = "$relPath ($bytes bytes)";
        }
    }
}

$pageTitle = 'Install2';
include __DIR__ . '/includes/header.php';
?>
<div class="d-flex align-items-center mb-3 gap-2">
    <h5 class="mb-0"><i class="bi bi-download me-2"></i>Module Installer 2 — Retry</h5>
</div>
<?php if ($done): ?>
<div class="alert alert-success">
    <strong><?= count($done) ?> file(s) written:</strong>
    <ul class="mb-0 mt-2"><?php foreach ($done as $f): ?><li><code><?= h($f) ?></code></li><?php endforeach; ?></ul>
</div>
<?php endif; ?>
<?php if ($errors): ?>
<div class="alert alert-danger">
    <strong>Errors:</strong>
    <ul class="mb-0 mt-2"><?php foreach ($errors as $e): ?><li><?= h($e) ?></li><?php endforeach; ?></ul>
</div>
<?php endif; ?>
<?php if (!$done): ?>
<div class="card border-0 shadow-sm mb-3" style="max-width:600px">
    <div class="card-body">
        <p>Retry writing 7 files that failed in install.php:</p>
        <ul class="small mb-3"><?php foreach (array_keys($files) as $f): ?><li><code><?= h($f) ?></code></li><?php endforeach; ?></ul>
        <form method="post">
            <button type="submit" name="go" value="1" class="btn btn-dark"
                    onclick="return confirm('Write these files now?')">
                <i class="bi bi-play-fill me-1"></i> Install Now
            </button>
        </form>
    </div>
</div>
<?php endif; ?>
<?php if ($done && !$errors): ?>
<div class="alert alert-info"><strong>Done!</strong> Delete this file (install2.php) from the server.</div>
<?php endif; ?>
<?php include __DIR__ . '/includes/footer.php'; ?>